/* src/menu/marena_asem_mng.cpp - async loader of the arena assembly list: one CD block of 0x24800 bytes at LSN id
 * 0x1073 (0x120-byte stAutoGenerateData records) read into a menu-heap buffer. SetUp resets the state, Play runs one
 * loader step per call (0: allocate + start the read, 1: wait for the async read, 2: mark done, 3: idle) and returns
 * the step; GetAsemData / GetAsemDataByIndex hand out the buffer / record i, Cleanup frees it, Init zeroes the state
 * at boot. The original Play calls the steps through a function-local pointer table (OLMENU 0x1edaa80) indexed by
 * the step byte; the native uses a table of its own (same entries, NULL for step 3). */
#include <string.h>
#include "acnb/local/src/menu/marena_asem_mng.h"

static void __MArenaAsemMng_DataReadEnd(void)
{
    s_stArenaAsemMng.step = 3;
}

static void __MArenaAsemMng_DataReading(void)
{
    PS2_FRAME(0x10);
    if (File_IsAsyncBusy() == 0) s_stArenaAsemMng.step = 2;
}

static void __MArenaAsemMng_DataReadStart(void)
{
    PS2_FRAME(0x10);
    s_stArenaAsemMng.pAsemData = (char *)DF_MMM_Alloc(0, 0x24800);
    if (s_stArenaAsemMng.pAsemData != 0) {
        Cdvd_ReadLsnBlind(0x1073, s_stArenaAsemMng.pAsemData, 0, 0);
        s_stArenaAsemMng.step = 1;
    }
}

char *MArenaAsemMng_GetAsemDataByIndex(int index)
{
    return s_stArenaAsemMng.pAsemData + index * 0x120;
}

char *MArenaAsemMng_GetAsemData(void)
{
    return s_stArenaAsemMng.pAsemData;
}

void MArenaAsemMng_Cleanup(void)
{
    PS2_FRAME(0x10);
    DF_MMM_Free(0, s_stArenaAsemMng.pAsemData);
    s_stArenaAsemMng.pAsemData = 0;
}

int MArenaAsemMng_Play(void)
{
    PS2_FRAME(0x10);
    static void (*const pFuncTable[4])(void) = {
        __MArenaAsemMng_DataReadStart,
        __MArenaAsemMng_DataReading,
        __MArenaAsemMng_DataReadEnd,
        0,
    };
    void (*f)(void) = pFuncTable[(int)s_stArenaAsemMng.step];   /* step 0-3, no bounds check in the original */

    if (f != 0) f();
    return s_stArenaAsemMng.step;
}

void MArenaAsemMng_SetUp(void)
{
    PS2_FRAME(0x10);
    if (s_stArenaAsemMng.pAsemData != 0) {
        DF_MMM_Free(0, s_stArenaAsemMng.pAsemData);
        s_stArenaAsemMng.pAsemData = 0;
    }
    s_stArenaAsemMng.step = 0;
}

void MArenaAsemMng_Init(void)
{
    PS2_FRAME(0x10);
    memset(&s_stArenaAsemMng, 0, 8);
    s_stArenaAsemMng.step = 0;
}
